script:
frappe.ui.form.on('Sales Invoice', {
	refresh(frm) {
		if (frm.is_new() || frm.doc.docstatus !== 1) { return; }
		const show = (m) => frappe.msgprint({ title: __('MyInvois'), indicator: (m.status === 'Rejected' || m.status === 'Cancelled') ? 'red' : 'green', message: m.message });
		frm.add_custom_button(__('Validate for MyInvois'), function () {
			frappe.call({ method: 'my_invois.my_invois.api.validate_for_myinvois', args: { doc_name: frm.doc.name }, freeze: true, callback: function (r) {
				const m = r.message || {};
				if (m.errors && m.errors.length) {
					frappe.msgprint({ title: __('Validation failed'), indicator: 'red', message: m.errors.join('<br>') });
				} else {
					frappe.msgprint({ title: __('Ready for MyInvois'), indicator: 'green', message: __('All required MyInvois data is present.') });
				}
			} });
		}, __('MyInvois'));
		frm.add_custom_button(__('Submit to MyInvois'), function () {
			frappe.call({ method: 'my_invois.my_invois.api.submit_to_myinvois', args: { doc_name: frm.doc.name }, freeze: true, callback: function (r) {
				show(r.message || {});
				frm.reload_doc();
			} });
		}, __('MyInvois'));
		if (frm.doc.myinvois_document_uuid) {
			frm.add_custom_button(__('Get LHDN Response'), function () {
				frappe.call({ method: 'my_invois.my_invois.api.refresh_myinvois_status', args: { doc_name: frm.doc.name }, freeze: true, callback: function (r) {
					show(r.message || {});
					frm.reload_doc();
				} });
			}, __('MyInvois'));
			frm.add_custom_button(__('Cancel at LHDN'), function () {
				frappe.prompt({ fieldname: 'reason', fieldtype: 'Data', label: __('Cancellation reason'), reqd: 1 }, function (values) {
					frappe.call({ method: 'my_invois.my_invois.api.cancel_myinvois_document', args: { doc_name: frm.doc.name, reason: values.reason }, freeze: true, callback: function (r) {
						show(r.message || {});
						frm.reload_doc();
					} });
				}, __('Cancel e-Invoice at LHDN'), __('Cancel'));
			}, __('MyInvois'));
		}
	}
});
